content.text:
{
  "name": "TCP数值服务组件",
  "name_en": "TCP Value Serving Component",
  "manufacturer": "",
  "description": "一个非物理的软件网络组件，用于在本地网络上通过 TCP 对外提供数值或消息，便于实验系统中的不同进程或设备之间共享实时数据。",
  "description_en": "A non-physical software networking component that serves values or messages over TCP on a local network, enabling real-time data sharing between processes or devices in an experimental system.",
  "actions": [
    {
      "action_name": "auto-send",
      "description": "通过指定的套接字发送消息数据。",
      "description_en": "Send message data through a specified socket."
    },
    {
      "action_name": "auto-run",
      "description": "运行 TCP 数值服务，将给定数值在本地网络上持续对外提供。",
      "description_en": "Run the TCP value service and continuously make the provided values available on the local network."
    },
    {
      "action_name": "auto-shutdown",
      "description": "关闭 TCP 数值服务并停止网络通信。",
      "description_en": "Shut down the TCP value service and stop network communication."
    }
  ],
  "tag_hints": [
    "TCP networking",
    "value serving",
    "local network data sharing",
    "inter-process communication",
    "telemetry streaming",
    "experiment software component"
  ]
}

